mapper.select:
SELECT DATE(o.create_time) as date, COUNT(DISTINCT o.id) as orderCount, SUM(o.total_amount) as totalAmount, COALESCE(SUM(oi.quantity), 0) as totalItems FROM tb_order o LEFT JOIN tb_order_item oi ON o.id = oi.order_id WHERE o.status IN (1,2,3) AND o.create_time >= #{startDate}
AND o.create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY DATE(o.create_time) ORDER BY date ASC

SELECT DATE(create_time) as date, SUM(total_amount) as totalAmount FROM tb_order WHERE status IN (1,2,3) AND create_time >= #{startDate}
AND create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY DATE(create_time) ORDER BY date ASC
